        <div
          className={cn(
            "w-4 h-4 bg-white rounded-full transition-transform shadow-sm",
            value ? "translate-x-0" : "translate-x-6",
          )}
        />
      </div>
      <span className="text-xs font-black text-brand-text">{label}</span>
