      limit(500)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as LoginLog));
      setLogs(data);
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, [isAdmin]);

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const matchesSearch = 
        log.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        log.code?.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesStatus = statusFilter === "all" || log.status === statusFilter;

      return matchesSearch && matchesStatus;
    });
  }, [searchTerm, statusFilter, logs]);

  const handleDelete = async (id: string) => {
    try {
      await deleteDoc(doc(db, "loginLogs", id));
      setDeleteConfirm(null);
    } catch (err) {
      handleFirestoreError(err, OperationType.DELETE, `loginLogs/${id}`);
    }
  };

  const handleClearAll = async () => {
    setIsDeleting(true);
    try {
      const q = query(collection(db, "loginLogs"));
      const snapshot = await getDocs(q);
      const batch = writeBatch(db);
      snapshot.docs.forEach((doc) => {
        batch.delete(doc.ref);
      });
      await batch.commit();
      setDeleteConfirm(null);
    } catch (err) {
      handleFirestoreError(err, OperationType.DELETE, "loginLogs");
    } finally {
      setIsDeleting(false);
    }
  };

  const exportToExcel = () => {
    const exportData = filteredLogs.map(log => ({
      'الاسم': log.name || 'غير معروف',
      'الكود': log.code || '-',
      'نوع الحساب': log.role === 'admin' ? 'مدير' : 'طالب',
      'تاريخ الدخول': format(new Date(log.loginAt), 'yyyy-MM-dd'),
      'وقت الدخول': log.loginTime,
      'حالة الدخول': log.status,
      'الجهاز': log.deviceInfo
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Login Logs");
    XLSX.writeFile(wb, `سجل_الدخول_${format(new Date(), 'yyyy-MM-dd')}.xlsx`);
  };

  return (
    <div className="min-h-screen bg-brand-cream p-6 lg:p-12 font-bold" dir="rtl">
      <div className="max-w-7xl mx-auto space-y-8">

        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <Link to="/admin" className="p-3 bg-white rounded-2xl shadow-sm hover:scale-110 transition-transform group">
              <ArrowRight className="w-6 h-6 text-brand-beige group-hover:text-brand-red" />
            </Link>
            <div>
              <h1 className="text-4xl font-black text-brand-text">سجل الدخول</h1>
              <p className="text-brand-beige mt-1">متابعة حركة الدخول للمنصة</p>
            </div>
          </div>

          <div className="flex flex-wrap gap-4">
            <button
              onClick={() => setDeleteConfirm("all")}
              disabled={logs.length === 0}
              className="flex items-center gap-3 px-6 py-4 bg-white border border-brand-beige/20 text-brand-red rounded-2xl shadow-sm hover:bg-rose-50 transition-all disabled:opacity-30"
            >
              <Trash2 className="w-5 h-5" />
              <span>مسح كل السجلات</span>
            </button>
            <button
              onClick={exportToExcel}
              className="flex items-center gap-3 px-6 py-4 bg-emerald-600 text-white rounded-2xl shadow-lg hover:bg-emerald-700 transition-all active:scale-95"
            >
              <FileSpreadsheet className="w-6 h-6" />
              <span>تصدير سجل الدخول</span>
            </button>
          </div>
        </div>

        {/* Confirmation Modal */}
        <AnimatePresence>
          {deleteConfirm && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-brand-text/40 backdrop-blur-sm z-[200] flex items-center justify-center p-6 text-right"
            >
              <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-white rounded-[32px] p-10 max-w-md w-full shadow-2xl"
              >
                <div className="w-16 h-16 bg-rose-50 rounded-2xl flex items-center justify-center text-brand-red mb-6 mx-auto">
                  <AlertTriangle className="w-8 h-8" />
                </div>
                <h3 className="text-2xl font-black text-brand-text mb-4 text-center">
                  {deleteConfirm === "all" ? "مسح كل السجلات؟" : "مسح السجل؟"}
                </h3>
                <p className="text-brand-beige mb-8 font-bold text-center">
                  {deleteConfirm === "all" 
                    ? "هل أنت متأكد من مسح كل سجلات الدخول؟ لا يمكن التراجع عن هذا الإجراء." 
                    : "هل أنت متأكد من مسح هذا السجل؟"}
                </p>
                <div className="flex gap-4">
                  <button
                    onClick={() => setDeleteConfirm(null)}
                    className="flex-1 py-4 bg-brand-cream text-brand-beige rounded-2xl font-black"
                  >
                    إلغاء
                  </button>
                  <button
                    onClick={() => deleteConfirm === "all" ? handleClearAll() : handleDelete(deleteConfirm)}
                    disabled={isDeleting}
                    className="flex-1 py-4 bg-brand-red text-white rounded-2xl font-black shadow-lg shadow-brand-red/10"
                  >
                    {isDeleting ? "جاري المسح..." : "تأكيد المسح"}
                  </button>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Filters */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="relative group">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-brand-beige group-focus-within:text-brand-red transition-colors" />
            <input
              type="text"
              placeholder="ابحث بالاسم أو الكود..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-white border-2 border-transparent focus:border-brand-red/20 rounded-2xl py-4 pr-12 pl-6 outline-none shadow-sm transition-all"
            />
          </div>

          <div className="relative">
            <Filter className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-brand-beige" />
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="w-full bg-white border-2 border-transparent focus:border-brand-red/20 rounded-2xl py-4 pr-12 pl-6 outline-none shadow-sm transition-all appearance-none cursor-pointer"
            >
              <option value="all">كل الحالات</option>
              <option value="ناجح">ناجح</option>
              <option value="فشل">فشل</option>
            </select>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-[32px] overflow-hidden shadow-xl shadow-brand-red/5 border border-brand-beige/10">
          <div className="overflow-x-auto">
            <table className="w-full text-right">
              <thead>
                <tr className="bg-brand-cream/50 text-brand-beige text-xs uppercase tracking-[0.2em]">
                  <th className="px-8 py-6">رقم</th>
                  <th className="px-8 py-6">الاسم</th>
                  <th className="px-8 py-6">الكود</th>
                  <th className="px-8 py-6">نوع الحساب</th>
                  <th className="px-8 py-6">التاريخ والوقت</th>
                  <th className="px-8 py-6">الحالة</th>
                  <th className="px-8 py-6">الجهاز</th>
                  <th className="px-8 py-6 text-center">إجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-brand-cream">
                {isLoading ? (
                  Array.from({ length: 5 }).map((_, i) => (
                    <tr key={i} className="animate-pulse">
                      <td colSpan={8} className="px-8 py-6">
                        <div className="h-4 bg-brand-cream rounded-full w-full" />
                      </td>
                    </tr>
                  ))
                ) : filteredLogs.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="px-8 py-12 text-center text-brand-beige">
                      لا يوجد نتائج للبحث
                    </td>
                  </tr>
                ) : (
                  filteredLogs.map((log, index) => (
                    <tr key={log.id} className="hover:bg-brand-cream/20 transition-colors group">
                      <td className="px-8 py-6 text-brand-beige">{filteredLogs.length - index}</td>
                      <td className="px-8 py-6 text-brand-text">
                        {log.name || (log.role === 'admin' ? 'المدير' : 'غير معروف')}
                      </td>
                      <td className="px-8 py-6 font-mono text-sm tracking-widest text-brand-beige">
                        {log.code || '-'}
                      </td>
                      <td className="px-8 py-6">
                        <span className={`px-4 py-1.5 rounded-full text-xs font-black ${
                          log.role === 'admin' 
                            ? 'bg-amber-100 text-amber-600' 
                            : 'bg-blue-100 text-blue-600'
                        }`}>
                          {log.role === 'admin' ? 'مدير' : 'طالب'}
                        </span>
                      </td>
                      <td className="px-8 py-6">
                        <div className="flex flex-col">
                          <span className="text-brand-text">{log.loginTime}</span>
                          <span className="text-xs text-brand-beige">
                            {format(new Date(log.loginAt), 'd MMMM yyyy', { locale: ar })}
                          </span>
                        </div>
                      </td>
                      <td className="px-8 py-6">
                        <div className={`flex items-center gap-2 font-black ${
                          log.status === 'ناجح' ? 'text-emerald-600' : 'text-brand-red'
                        }`}>
                          {log.status === 'ناجح' ? <CheckCircle2 className="w-4 h-4" /> : <XCircle className="w-4 h-4" />}
                          <span>{log.status}</span>
                        </div>
                      </td>
                      <td className="px-8 py-6 transition-opacity opacity-40 group-hover:opacity-100">
                        <div className="flex items-center gap-2 text-xs">
                          <Monitor className="w-4 h-4" />
                          <span className="truncate max-w-[150px]" title={log.deviceInfo}>
                            {log.deviceInfo.split(')')[0] + ')'}
                          </span>
                        </div>
                      </td>
                      <td className="px-8 py-6 text-center">
                        <button
                          onClick={() => setDeleteConfirm(log.id!)}
                          className="p-3 hover:bg-rose-50 rounded-xl text-brand-beige hover:text-brand-red transition-all"
                          title="حذف"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { 
  collection, 
  onSnapshot, 
  addDoc, 
  deleteDoc, 
  doc, 
  query, 
  orderBy,
  setDoc,
  where
} from 'firebase/firestore';
import { db } from '../../lib/firebase';
import { useAuth } from '../../hooks/useAuth';
import { notificationService } from '../../lib/notificationService';
import { saturdaySchedules, thursdaySchedules, ScheduleItem } from '../../data/fixedSchedules';
import { 
  Calendar as CalendarIcon, 
  Plus, 
  Trash2, 
  Clock, 
  User as UserIcon, 
  Bell, 
  Check, 
  AlertCircle,
  HelpCircle,
  Search,
  BookOpen,
  Filter,
  Sparkles,
  Grid,
  List,
  Pin,
  TrendingUp,
  Share2,
  BookmarkCheck,
  Bookmark,
  ChevronLeft,
  Printer
} from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';

interface PrepMeeting {
  id: string;
  title: string;
  description: string;
  dateTime: string;
  createdAt: any;
  createdBy: string;
  creatorName: string;
  reminderSent12h: boolean;
}

const isPastDateTime = (dateTimeStr: string) => {
  return new Date(dateTimeStr).getTime() < Date.now();
};

export default function PreparationMeetings() {
  const { user, isAdmin } = useAuth();
  const [meetings, setMeetings] = useState<PrepMeeting[]>([]);
  const [loading, setLoading] = useState(true);
  const [notification, setNotification] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [now] = useState(() => Date.now());

  // Navigation: 'booklet' | 'saturday' | 'thursday' | 'prep_servants'
  const [activeTab, setActiveTab] = useState<'booklet' | 'saturday' | 'thursday' | 'prep_servants'>('booklet');

  // Style view: 'grid' | 'table'
  const [viewStyle, setViewStyle] = useState<'grid' | 'table'>('grid');

  // Topic types filters: 'all' | 'lessons' | 'exams' | 'special'
  const [filterType, setFilterType] = useState<'all' | 'lessons' | 'exams' | 'special'>('all');

  const [searchTerm, setSearchTerm] = useState('');

  // Form State for Custom Servant Prep meetings
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [dateTime, setDateTime] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Check scheduling privileges
  const canManageMeetings = isAdmin || user?.isMeetingScheduler === true;

  // Realtime subscription for user's favorites
  const [favoriteTopics, setFavoriteTopics] = useState<string[]>([]);

  useEffect(() => {
    if (!user?.uid) return;

    const q = query(
      collection(db, 'favorites'),
      where('userId', '==', user.uid)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const keys = snapshot.docs.map(docSnap => docSnap.id.replace(user.uid + "_", ""));
      setFavoriteTopics(keys);
    }, (error) => {
      console.error("Error fetching favorites:", error);
    });

    return () => unsubscribe();
  }, [user?.uid]);

  const getTopicKey = (type: 'saturday' | 'thursday', date: string) => {
    return `${type}_${date.trim().replace(/\s+/g, '')}`;
  };

  const isFavorite = (type: 'saturday' | 'thursday', date: string) => {
    return favoriteTopics.includes(getTopicKey(type, date));
  };

  const toggleFavorite = async (type: 'saturday' | 'thursday', item: any) => {
    if (!user?.uid) {
      triggerNotification('error', 'يرجى تسجيل الدخول أولاً لتحديد موضوعاتك المفضلة.');
      return;
    }

    const key = getTopicKey(type, item.date);
    const docId = `${user.uid}_${key}`;

    if (favoriteTopics.includes(key)) {
      try {
        await deleteDoc(doc(db, 'favorites', docId));
        triggerNotification('success', 'تم إزالة الموضوع من مفضلتك.');
      } catch (err) {
        console.error(err);
        triggerNotification('error', 'فشل في إزالة الموضوع من المفضلة.');
      }
    } else {
      try {
        await setDoc(doc(db, 'favorites', docId), {
          userId: user.uid,
          userEmail: user.email || "",
          type,
          date: item.date,
          topic1: item.topic1,
          topic2: item.topic2 || "",
          createdAt: new Date().toISOString(),
          notified: false
        });
        triggerNotification('success', 'تمت إضافة الموضوع لمفضلتك! ستحصل على تنبيه تذكيري قبل موعد المحاضرة المذكور. 🔔⭐');
      } catch (err) {
        console.error(err);
        triggerNotification('error', 'فشل في إضافة الموضوع للمفضلة.');
      }
    }
  };

  // Realtime subscription for meetings
  useEffect(() => {
    notificationService.checkAndInjectPrepMeetingReminders().catch(console.error);

    const q = query(
      collection(db, 'preparationMeetings'), 
      orderBy('dateTime', 'asc')
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(d => ({
        id: d.id,
        ...d.data()
      })) as PrepMeeting[];
      setMeetings(data);
      setLoading(false);
    }, (error) => {
      console.error("Error fetching meetings:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const triggerNotification = (type: 'success' | 'error', text: string) => {
    setNotification({ type, text });
    setTimeout(() => setNotification(null), 4000);
  };

  const handleCreateMeeting = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canManageMeetings) {
      triggerNotification('error', 'عذراً، ليس لديك الصلاحية لجدولة الاجتماعات.');
      return;
    }

    if (!title.trim() || !dateTime || !description.trim()) {
      triggerNotification('error', 'يرجى ملء جميع الحقول المطلوبة!');
      return;
    }

    if (isPastDateTime(dateTime)) {
      triggerNotification('error', 'لا يمكن جدولة اجتماع في الماضي!');
      return;
    }

    setIsSubmitting(true);
    try {
      await addDoc(collection(db, 'preparationMeetings'), {
        title: title.trim(),
        description: description.trim(),
        dateTime,
        createdAt: new Date().toISOString(),
        createdBy: user?.uid || 'unknown',
        creatorName: user?.fullName || 'مسؤول الخدمة',
        reminderSent12h: false,
        immediateSent: true
      });

      const dateFormatted = new Date(dateTime).toLocaleString('ar-EG', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        hour12: true
      });

      await notificationService.sendNotification({
        title: `📅 اجتماع تحضيري جديد للخدمة`,
        message: `تمت جدولة اجتماع تحضيري رئيسي جديد بعنوان "${title.trim()}" يوم (${dateFormatted}). يرجى من جميع الخدام الاستعداد وتجهيز الفقرات للخدمة! ⛪📿`,
        type: 'info',
        category: 'announcements',
        targetGroups: ['servant']
      });

      triggerNotification('success', 'تم جدولة الاجتماع بنجاح وإرسال إشعار فوري لجميع الخدام! 🔔');

      setTitle('');
      setDescription('');
      setDateTime('');
    } catch (err: any) {
      console.error(err);
      triggerNotification('error', 'حدث خطأ أثناء جدولة الاجتماع، يرجى المحاولة لاحقاً.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteMeeting = async (id: string, meetingTitle: string) => {
    if (!canManageMeetings) return;
    if (!window.confirm(`هل أنت متأكد من حذف اجتماع: "${meetingTitle}"؟`)) return;

    try {
      await deleteDoc(doc(db, 'preparationMeetings', id));
      triggerNotification('success', 'تم إلغاء وحذف الاجتماع بنجاح.');
    } catch (err) {
      console.error(err);
      triggerNotification('error', 'فشل حذف الاجتماع.');
    }
  };

  // Date Parsing Utilities to find "Next Upcoming" based on Year 2026
  const getParsedDate = (itemDate: string): Date => {
    const parts = itemDate.split('/');
    const day = parseInt(parts[0]?.trim() || '1');
    const month = parseInt(parts[1]?.trim() || '1') - 1; // 0-indexed month
    return new Date(2026, month, day, 19, 0, 0); // Saturday/Thursday approx 7 PM
  };

  // Determine if a meeting is the immediate upcoming one
  const getUpcomingItem = (items: ScheduleItem[]): ScheduleItem | null => {
    const sorted = [...items]
      .map(item => ({ ...item, dateObj: getParsedDate(item.date) }))
      .filter(item => item.dateObj.getTime() >= now)
      .sort((a, b) => a.dateObj.getTime() - b.dateObj.getTime());

    return sorted.length > 0 ? sorted[0] : null;
  };

  const nextSaturdayMeeting = getUpcomingItem(saturdaySchedules);
  const nextThursdayMeeting = getUpcomingItem(thursdaySchedules);

  // Apply filters on lists
  const filterSchedule = (schedule: ScheduleItem[]) => {
    return schedule.filter(item => {
      // 1. Text Search matching
      const matchesSearch = 
        item.topic1.toLowerCase().includes(searchTerm.toLowerCase()) || 
        (item.topic2 && item.topic2.toLowerCase().includes(searchTerm.toLowerCase())) ||
        item.date.includes(searchTerm);

      if (!matchesSearch) return false;

      // 2. Type filters
      if (filterType === 'exams') {
        return item.topic1.includes('امتحان') || (item.topic2 && item.topic2.includes('امتحان'));
      }
      if (filterType === 'special') {
        return item.isSpecialEvent === true;
      }
      if (filterType === 'lessons') {
        const isExam = item.topic1.includes('امتحان') || (item.topic2 && item.topic2.includes('امتحان'));
        return !item.isSpecialEvent && !isExam;
      }

      return true;
    });
  };

  const filteredSaturdays = filterSchedule(saturdaySchedules);
  const filteredThursdays = filterSchedule(thursdaySchedules);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="p-4 md:p-10 max-w-7xl mx-auto space-y-8 print:p-0 print:bg-white" dir="rtl">
      {/* Toast Notification */}
      <AnimatePresence>
        {notification && (
          <motion.div
            id="toast-notification"
            initial={{ opacity: 0, y: -20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -20, scale: 0.95 }}
            className={`fixed top-6 left-6 right-6 md:left-auto md:w-96 p-4 rounded-2xl shadow-xl z-50 flex items-center gap-3 border ${
              notification.type === 'success' 
                ? 'bg-emerald-50 border-emerald-100 text-emerald-800' 
                : 'bg-rose-50 border-rose-100 text-brand-red'
            }`}
          >
            {notification.type === 'success' ? (
              <div className="w-8 h-8 rounded-full bg-emerald-500 flex items-center justify-center shrink-0">
                <Check className="w-4 h-4 text-white" />
              </div>
            ) : (
              <div className="w-8 h-8 rounded-full bg-rose-500 flex items-center justify-center shrink-0">
                <AlertCircle className="w-4 h-4 text-white" />
              </div>
            )}
            <p className="text-xs md:text-sm font-bold leading-relaxed">{notification.text}</p>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Header Banner - hidden on print */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-brand-text p-6 md:p-8 rounded-[32px] md:rounded-[40px] shadow-2xl relative overflow-hidden text-white print:hidden">
        <div className="absolute inset-0 bg-gradient-to-r from-brand-red/10 to-transparent pointer-events-none" />
        <div className="flex items-center gap-4 relative z-10">
          <div className="w-14 h-14 bg-brand-red rounded-2xl flex items-center justify-center shadow-lg shadow-brand-red/20 shrink-0">
            <CalendarIcon className="text-white w-7 h-7" />
          </div>
          <div>
            <h1 className="text-2xl md:text-3xl font-black tracking-tight leading-tight">جدول المناهج والاجتماعات</h1>
            <p className="text-xs md:text-sm opacity-60 font-medium mt-1">المناهج المعتمدة رسمياً والمحاضرات المقررة بالإضافة إلى مواعيد اجتماعات الخدام</p>
          </div>
        </div>
        <div className="flex items-center gap-3 relative z-10 shrink-0 self-start md:self-auto">
          <button 
            id="btn-print"
            onClick={handlePrint}
