            </div>
          )}

          {newQuestion.type === 'true-false' && (
            <div className="space-y-3 bg-brand-cream/10 p-4 rounded-2xl border border-brand-beige/5">
              <label className="text-xs font-black text-brand-text block mb-1">حدد الإجابة الصحيحة:</label>
              <div className="flex gap-4">
                {['صح', 'خطأ'].map(val => (
                  <button
                    key={val}
                    type="button"
                    onClick={() => setNewQuestion({...newQuestion, correctAnswer: val})}
                    className={`flex-1 py-4 rounded-xl text-sm font-black transition-all border-2 ${newQuestion.correctAnswer === val ? (val === 'صح' ? 'bg-emerald-500 border-emerald-600 text-white' : 'bg-rose-500 border-rose-600 text-white') : 'bg-white border-gray-200 text-brand-text hover:bg-gray-50'}`}
                  >
                    {val}
                  </button>
                ))}
              </div>
            </div>
          )}

          {newQuestion.type === 'short-answer' && (
            <div className="space-y-3 bg-brand-cream/10 p-4 rounded-2xl border border-brand-beige/5">
              <label className="text-xs font-black text-brand-text block mb-1 font-sans">الإجابة المقالية النموذجية (الاسترشادية لتصحيح المعلم أو الذكاء الاصطناعي):</label>
              <input 
                className="w-full p-4 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-brand-red/20 text-sm font-bold" 
                placeholder="اكتب الإجابة النموذجية الصحيحة هنا..." 
                value={newQuestion.correctAnswer} 
                onChange={e => setNewQuestion({...newQuestion, correctAnswer: e.target.value})} 
              />
            </div>
          )}

          <button onClick={handleCreate} className="w-full md:w-auto px-10 py-4 bg-brand-red text-white font-black rounded-xl flex gap-2 items-center justify-center hover:scale-[1.01] active:scale-[0.99] transition-all">
            <Plus className="w-5 h-5"/> إضافة السؤال لبنك الأسئلة
          </button>
        </div>
      </div>

      <div className="space-y-4">
        {/* Filters */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-brand-cream/30 p-4 rounded-2xl border border-brand-beige/10">
          <div className="flex flex-wrap gap-2 items-center">
            <Filter className="w-4 h-4 text-brand-beige" />
            <span className="text-xs font-black text-brand-text">تصفية حسب القسم:</span>
            {['الكل', 'العهد الجديد', 'العهد القديم', 'طقوس', 'عام'].map(cat => (
              <button 
                key={cat} 
                onClick={() => setFilterCategory(cat)}
                className={`px-3 py-1.5 rounded-lg text-xs font-black whitespace-nowrap transition-all ${filterCategory === cat ? 'bg-brand-red text-white' : 'bg-white text-gray-500 border border-gray-200 hover:bg-gray-50'}`}
              >
                {cat}
              </button>
            ))}
          </div>

          <div className="flex flex-wrap gap-2 items-center">
            <span className="text-xs font-black text-brand-text">حسب شكل السؤال:</span>
            {[
              { id: 'الكل', label: 'الكل' },
              { id: 'multiple-choice', label: 'اختيار من متعدد' },
              { id: 'true-false', label: 'صح أو خطأ' },
              { id: 'short-answer', label: 'مقالي/قصير' }
            ].map(typeItem => (
              <button 
                key={typeItem.id} 
                onClick={() => setFilterType(typeItem.id)}
                className={`px-3 py-1.5 rounded-lg text-xs font-black whitespace-nowrap transition-all ${filterType === typeItem.id ? 'bg-brand-text text-white' : 'bg-white text-gray-500 border border-gray-200 hover:bg-gray-50'}`}
              >
                {typeItem.label}
              </button>
            ))}
          </div>
        </div>

        {loading ? (
          <div className="py-20 text-center">
            <div className="w-10 h-10 border-4 border-brand-red border-t-transparent rounded-full animate-spin mx-auto mb-4" />
            <p className="font-bold text-gray-400">جاري تحميل الأسئلة...</p>
          </div>
        ) : questions.length === 0 ? (
          <p className="text-center font-bold text-gray-400 py-16 bg-white rounded-3xl border border-gray-100">البنك فارغ حالياً</p>
        ) : (
          <div className="grid md:grid-cols-2 gap-6">
            {questions
              .filter(q => filterCategory === 'الكل' || q.category === filterCategory)
              .filter(q => filterType === 'الكل' || q.type === filterType)
              .map(q => (
                <div key={q.id} className="bg-white p-6 rounded-[32px] border border-brand-beige/10 flex flex-col justify-between group hover:shadow-xl hover:shadow-brand-red/5 transition-all">
                  <div>
                    <div className="flex flex-wrap justify-between items-start gap-2 mb-3">
                      <div className="flex gap-1.5">
                        <span className="bg-brand-cream/50 text-brand-text px-3 py-1 rounded-lg text-xs font-black">{q.category || 'غير محدد'}</span>
                        <span className={`px-2.5 py-1 rounded-lg text-[10px] font-black uppercase ${
                          q.type === 'multiple-choice' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' :
                          q.type === 'true-false' ? 'bg-amber-50 text-amber-700 border border-amber-100' :
                          'bg-blue-50 text-blue-700 border border-blue-100'
                        }`}>
                          {q.type === 'multiple-choice' ? 'اختيار من متعدد' : 
                           q.type === 'true-false' ? 'صح أو خطأ' : 'إجابة مقالية'}
                        </span>
                      </div>
                      <div className="flex items-center gap-1.5 text-[10px] font-bold text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">
                        <User className="w-3 h-3" />
                        <span>بواسطة: {q.createdBy || 'مجهول'}</span>
                      </div>
                    </div>
                    <p className="font-extrabold text-brand-text mb-4 text-base md:text-lg leading-relaxed">{q.text}</p>

                    <div className="space-y-2 bg-gray-50/70 p-4 rounded-2xl border border-gray-100">
                      <p className="text-xs font-black text-brand-beige">الإجابة النموذجية الصحيحة:</p>
                      <p className="text-sm font-black text-emerald-600 flex items-center gap-2">
                        <span className="w-5 h-5 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center text-xs">✓</span>
                        {q.correctAnswer}
                      </p>
                      {q.type === 'multiple-choice' && q.options?.map((opt: string, i: number) => opt && (
                        <p key={i} className="text-sm text-gray-500 font-medium flex items-center gap-2">
                          <span className="w-5 h-5 rounded-full bg-gray-200 text-gray-500 flex items-center justify-center text-xs">✗</span>
                          {opt}
                        </p>
                      ))}
                    </div>
                  </div>

                  <div className="flex justify-end mt-4 pt-4 border-t border-brand-cream/50">
                    <button onClick={() => handleDelete(q.id)} className="text-brand-red flex items-center gap-2 bg-rose-50 px-4 py-2 hover:bg-rose-100 transition-colors rounded-xl text-xs font-black">
                      <Trash2 className="w-4 h-4" /> حذف السؤال
                    </button>
                  </div>
                </div>
              ))}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from "react";
import {
  collection,
  query,
  orderBy,
  onSnapshot,
  doc,
  updateDoc,
  getDoc,
  where,
  writeBatch,
  getDocs,
} from "firebase/firestore";
import { db, handleFirestoreError, OperationType } from "../../lib/firebase";
import { Submission, UserAnswer, Question, Assessment } from "../../types";
import { useAuth } from "../../hooks/useAuth";
import { useLocation } from "react-router-dom";
import {
  ArrowLeft,
  Download,
  Search,
  History,
  Star,
  Trophy,
  Users as UsersIcon,
  X,
  MessageSquare,
  Save,
  Edit,
  Eye,
  Filter,
  ListChecks,
  ArrowUpDown,
  Info,
  ChevronRight,
  Trash2,
  CheckCircle,
  AlertTriangle,
  Church,
  Clock,
  XCircle
} from "lucide-react";
import { Link } from "react-router-dom";
import { motion, AnimatePresence } from "motion/react";
import { formatDate, cn } from "../../lib/utils";
import * as XLSX from "xlsx";
import { SmartImage } from "../../components/ui/SmartImage";
import { deleteDoc } from "firebase/firestore";

import { exportToCSV } from "../../lib/csv";

export default function ResultsDashboard() {
  const location = useLocation();
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [participantFilter, setParticipantFilter] = useState("");
  const [assessmentFilter, setAssessmentFilter] = useState("");
  const [dateRange, setDateRange] = useState<{ start: string; end: string }>({
    start: "",
    end: "",
  });
  const [selectedSubmission, setSelectedSubmission] = useState<Submission | null>(null);
  const [deleteConfirm, setDeleteConfirm] = useState<Submission | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const { isAdmin } = useAuth();
  const [userPhotos, setUserPhotos] = useState<Record<string, string>>({});

  // Filters
  const [statusFilter, setStatusFilter] = useState<
    "all" | "reviewed" | "pending"
  >("pending");
  const [difficultyFilter, setDifficultyFilter] = useState<
    "all" | "easy" | "medium" | "hard"
  >("all");
  const [sortBy, setSortBy] = useState<"date" | "score" | "streak">("date");
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");

  useEffect(() => {
    if (!isAdmin) return;

    const unsubscribePhotos = onSnapshot(query(collection(db, "users"), where("role", "==", "student")), (usersSnap) => {
      const photoMap: Record<string, string> = {};
      usersSnap.forEach(doc => {
        const data = doc.data() as any;
        if (data.photoUrl) photoMap[doc.id] = data.photoUrl;
      });
      setUserPhotos(photoMap);
    }, (err) => {
      console.error("Error fetching user photos:", err);
    });

    const q = query(collection(db, "submissions"), orderBy("date", "desc"));
    const unsubscribeSubmissions = onSnapshot(
      q,
      (snapshot) => {
        const data = snapshot.docs.map(
          (doc) => ({ id: doc.id, ...doc.data() }) as Submission,
        );
        setSubmissions(data);
        setIsLoading(false);
      },
      (error) => {
        handleFirestoreError(error, OperationType.LIST, "submissions");
      },
    );

    return () => {
      unsubscribePhotos();
      unsubscribeSubmissions();
    };
  }, [isAdmin]);

  const handleDelete = async (id: string) => {
    setIsDeleting(true);
    try {
      if (id === "all") {
        const batch = writeBatch(db);
        const q = query(collection(db, "submissions"));
        const snapshot = await getDocs(q);
        snapshot.docs.forEach((doc) => batch.delete(doc.ref));
        await batch.commit();
      } else {
        await deleteDoc(doc(db, "submissions", id));
      }
      setDeleteConfirm(null);
    } catch (err) {
      handleFirestoreError(err, OperationType.DELETE, `submissions/${id}`);
    } finally {
      setIsDeleting(false);
    }
  };

  const updateUserStatsAfterAdjustment = async (submission: Submission, scoreDelta: number) => {
    if (!submission.participantId) return;

    try {
      const userRef = doc(db, "users", submission.participantId);
      const userSnap = await getDoc(userRef);

      if (userSnap.exists()) {
        const userData = userSnap.data() as User;
        await updateDoc(userRef, {
          totalPoints: (userData.totalPoints || 0) + scoreDelta,
          cumulativePoints: (userData.cumulativePoints || userData.totalPoints || 0) + scoreDelta
        });
      }
    } catch (err) {
      console.error("Failed to update user stats", err);
    }
  };

  const handleScoreUpdate = async (
    sub: Submission,
    qId: string,
    newScore: number,
    reason: string,
  ) => {
    const oldAnswer = sub.answers.find((ans) => ans.questionId === qId);
    if (!oldAnswer) return;

    const previousScore = oldAnswer.score;
    const scoreDelta = newScore - previousScore;

    const newAnswers = sub.answers.map((ans) => {
      if (ans.questionId === qId) {
        return {
          ...ans,
          score: newScore,
          isCorrect: newScore > 0,
          originalAiScore: ans.originalAiScore ?? previousScore,
          adminNote: reason,
          lastAdjustedAt: new Date().toISOString(),
        };
      }
      return ans;
    });

    const newFinalScore =
      newAnswers.reduce((acc, curr) => acc + curr.score, 0) + (sub.adminAdjustment || 0);

    const auditEntry = {
      timestamp: new Date().toISOString(),
      adminId: "current-admin",
      previousScore: sub.finalScore,
      newScore: newFinalScore,
      reason: `Manual override for question ${qId}: ${reason}`,
    };

    try {
      await updateDoc(doc(db, "submissions", sub.id!), {
        answers: newAnswers,
        finalScore: newFinalScore,
        isManuallyAdjusted: true,
        adjustmentAudit: [...(sub.adjustmentAudit || []), auditEntry],
      });

      await updateUserStatsAfterAdjustment(sub, scoreDelta);

      setSelectedSubmission({
        ...sub,
        answers: newAnswers,
        finalScore: newFinalScore,
        isManuallyAdjusted: true,
        adjustmentAudit: [...(sub.adjustmentAudit || []), auditEntry],
      });
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, `submissions/${sub.id}`);
    }
  };

  const handleAdminAdjustment = async (sub: Submission, amount: number, reason: string) => {
    const currentAdjust = sub.adminAdjustment || 0;
    if (currentAdjust === amount) return;

    const scoreDelta = amount - currentAdjust;

    const baseScore = sub.answers.reduce((acc, curr) => acc + curr.score, 0);
    const newFinalScore = baseScore + amount;

    const auditEntry = {
      timestamp: new Date().toISOString(),
      adminId: "current-admin",
      previousScore: sub.finalScore,
      newScore: newFinalScore,
      reason: `Manual total adjustment: ${reason}`,
    };

    try {
      await updateDoc(doc(db, "submissions", sub.id!), {
        adminAdjustment: amount,
        finalScore: newFinalScore,
        isManuallyAdjusted: true,
        adjustmentAudit: [...(sub.adjustmentAudit || []), auditEntry],
      });

      await updateUserStatsAfterAdjustment(sub, scoreDelta);

      setSelectedSubmission({
        ...sub,
        adminAdjustment: amount,
        finalScore: newFinalScore,
        isManuallyAdjusted: true,
        adjustmentAudit: [...(sub.adjustmentAudit || []), auditEntry],
      });
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, `submissions/${sub.id}`);
    }
  };

  const handleMarkAsReviewed = async (sub: Submission) => {
    try {
      await updateDoc(doc(db, "submissions", sub.id!), {
        isReviewed: true,
      });
      setSelectedSubmission({
        ...sub,
        isReviewed: true,
      });
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, `submissions/${sub.id}`);
    }
  };

  const filteredSubmissions = useMemo(() => {
    let result = submissions.filter((s) => {
      const matchesParticipant = s.participantName
        .toLowerCase()
        .includes(participantFilter.toLowerCase()) ||
        s.participantPhoneOrId.toLowerCase().includes(participantFilter.toLowerCase());
      const matchesAssessment = s.assessmentTitle
        .toLowerCase()
        .includes(assessmentFilter.toLowerCase());

      let matchesDate = true;
      if (dateRange.start) {
        matchesDate = matchesDate && new Date(s.date) >= new Date(dateRange.start);
      }
      if (dateRange.end) {
        // Set to end of day for the end date filter
        const endDate = new Date(dateRange.end);
        endDate.setHours(23, 59, 59, 999);
        matchesDate = matchesDate && new Date(s.date) <= endDate;
      }

      return matchesParticipant && matchesAssessment && matchesDate;
    });

    if (statusFilter === "reviewed")
      result = result.filter((s) => s.isReviewed);
    if (statusFilter === "pending")
      result = result.filter((s) => !s.isReviewed);

    // Sorting
    result.sort((a, b) => {
      let valA: any, valB: any;
      if (sortBy === "date") {
        valA = a.date;
        valB = b.date;
      } else if (sortBy === "score") {
        valA = a.finalScore / (a.maxScore || 1);
        valB = b.finalScore / (b.maxScore || 1);
      } else {
        valA = a.streakCount;
        valB = b.streakCount;
      }

      if (sortOrder === "asc") return valA > valB ? 1 : -1;
      return valA < valB ? 1 : -1;
    });

    return result;
  }, [submissions, participantFilter, assessmentFilter, dateRange, statusFilter, sortBy, sortOrder]);

  const exportToExcel = async () => {
    // We need to fetch assessment questions for full text in export
    const assessmentCache: Record<string, Assessment> = {};

    const exportData = await Promise.all(
      filteredSubmissions.map(async (s) => {
        let assessment = assessmentCache[s.assessmentId];
        if (!assessment) {
          try {
            const docRef = doc(db, "assessments", s.assessmentId);
            const docSnap = await getDoc(docRef);
            if (docSnap.exists()) {
              assessment = { id: docSnap.id, ...docSnap.data() } as Assessment;
              assessmentCache[s.assessmentId] = assessment;
            }
          } catch (e) {
            console.error(
              "Failed to fetch assessment for export",
              s.assessmentId,
            );
          }
        }

        const baseInfo: any = {
          "اسم المشارك": s.participantName,
          الكود: s.participantPhoneOrId,
          "عنوان الاختبار": s.assessmentTitle,
          "إصدار الاختبار": s.assessmentVersion || 1,
          التاريخ: new Date(s.date).toLocaleDateString("ar-EG"),
          الوقت: new Date(s.date).toLocaleTimeString("ar-EG"),
          "وقت بداية الاختبار": new Date(new Date(s.date).getTime() - (s.readingTimeSeconds + s.answeringTimeSeconds) * 1000).toLocaleTimeString("ar-EG"),
          "وقت التسليم": new Date(s.date).toLocaleTimeString("ar-EG"),
          "نوع التسليم": s.submittedManually ? "يدوي" : "تلقائي",
          "الأسئلة غير المجابة": s.unansweredCount || 0,
          "وقت القراءة (ثانية)": s.readingTimeSeconds,
          "وقت الحل (ثانية)": s.answeringTimeSeconds,
          "الالتزام الحالي": s.streakCount,
          "درجة الذكاء الاصطناعي":
            s.answers.reduce(
              (acc, a) => acc + (a.originalAiScore ?? a.score),
              0,
            ),
          "الدرجة النهائية": s.finalScore,
          "أقصى درجة ممكنة": s.maxScore,
          "النسبة المئوية": `${((s.finalScore / s.maxScore) * 100).toFixed(1)}%`,
          "تم التعديل يدوياً": s.isManuallyAdjusted ? "نعم" : "لا",
          "ملاحظات المراجعة": s.adminReviewNotes || "",
        };

        // Add dynamic columns for each question
        s.answers.forEach((ans, idx) => {
          const prefix = `Q${idx + 1}`;
          const assessmentQ = assessment
            ? [
                ...assessment.questions.easy,
                ...assessment.questions.medium,
                ...assessment.questions.hard,
              ].find((q) => q.id === ans.questionId)
            : null;

          baseInfo[`${prefix} Difficulty`] = ans.difficulty;
          baseInfo[`${prefix} Type`] = assessmentQ?.type || "N/A";
          baseInfo[`${prefix} Full Question`] = assessmentQ?.text || "N/A";
          baseInfo[`${prefix} Choices (MCQ)`] =
            assessmentQ?.options?.join(" | ") || "";
          baseInfo[`${prefix} Participant Answer`] = ans.userAnswer;
          baseInfo[`${prefix} Correct Benchmark`] = ans.correctAnswer;
          baseInfo[`${prefix} AI Score`] = ans.originalAiScore ?? ans.score;
          baseInfo[`${prefix} Final Score`] = ans.score;
          baseInfo[`${prefix} Max Points`] = ans.maxPoints;
          baseInfo[`${prefix} AI Feedback`] = ans.feedback || "";
          baseInfo[`${prefix} Admin Note`] = ans.adminNote || "";
          baseInfo[`${prefix} Outcome`] =
            ans.score === ans.maxPoints
              ? "Correct"
              : ans.score > 0
                ? "Partial"
                : "Incorrect";
        });

        return baseInfo;
      }),
    );

