                      </div>
                      <div className="flex-1 text-right">
                        <div className="flex items-center justify-between mb-2 flex-row-reverse">
                          <p className="text-sm font-black text-brand-text">
                            تعديل رقم {submission.adjustmentAudit!.length - idx}
                          </p>
