            categoryFilter !== "servants" ? "lg:col-span-3" : "lg:col-span-2"
          )}>
            <div className="relative w-full flex items-center flex-row-reverse text-right">
              <Search className="w-5 h-5 text-brand-beige ml-3 shrink-0" />
