export default function PostExamReview() {
  const { t, i18n } = useTranslation();
  const { submissionId } = useParams<{ submissionId: string }>();
  const [submission, setSubmission] = useState<Submission | null>(null);
  const [assessment, setAssessment] = useState<Assessment | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  useEffect(() => {
    async function fetchData() {
      if (!submissionId) return;
      try {
        const sSnap = await getDoc(doc(db, "submissions", submissionId));
        if (sSnap.exists()) {
          const sData = sSnap.data() as Submission;
          setSubmission(sData);

          const aSnap = await getDoc(doc(db, "assessments", sData.assessmentId));
          if (aSnap.exists()) {
            setAssessment(aSnap.data() as Assessment);
          }
        }
      } catch (err) {
        handleFirestoreError(err, OperationType.GET, `submissions/${submissionId}`);
      } finally {
        setIsLoading(false);
      }
    }
    fetchData();
  }, [submissionId]);

  if (isLoading) return <div className="min-h-screen flex items-center justify-center font-black text-brand-beige">{t('assessments.review_loading')}</div>;
  if (!submission || !assessment) return <div className="min-h-screen flex items-center justify-center font-black text-brand-beige">{t('assessments.review_not_found')}</div>;

  const scorePercentage = calculatePercentage(submission.finalScore, submission.maxScore);

  return (
    <div className={cn("min-h-screen bg-brand-cream p-6 lg:p-12 font-bold", i18n.language === 'ar' ? 'text-right' : 'text-left')} dir={i18n.language === 'ar' ? 'rtl' : 'ltr'}>
      <div className="max-w-4xl mx-auto space-y-12">

        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <Link to="/student" className="p-3 bg-white rounded-2xl shadow-sm hover:scale-110 transition-transform group">
              <ArrowRight className={cn("w-6 h-6 text-brand-beige group-hover:text-brand-red", i18n.language === 'en' ? 'rotate-180' : '')} />
            </Link>
            <div>
              <h1 className="text-4xl font-black text-brand-text tracking-tighter">{t('assessments.review_title')}</h1>
              <p className="text-brand-beige mt-1">{assessment.title}</p>
            </div>
          </div>

          <div className="flex items-center gap-4 bg-white px-8 py-4 rounded-[28px] border border-brand-beige/10 shadow-sm relative group">
             <div className="bg-brand-cream p-3 rounded-2xl text-brand-red">
               <Trophy className="w-6 h-6" />
             </div>
             <div className="flex flex-col">
               <span className="text-[10px] text-brand-beige uppercase tracking-widest leading-none mb-1">{t('assessments.total_score')} ({scorePercentage}%)</span>
               <div className="flex items-baseline gap-1">
                 <span className="text-3xl font-black text-brand-text">{submission.finalScore}</span>
                 <span className="text-brand-beige">/ {submission.maxScore}</span>
               </div>
             </div>

             {/* Score Breakdown Tooltip-like Info */}
             <div className="absolute top-full mt-2 left-0 right-0 bg-white p-4 rounded-2xl shadow-xl border border-brand-beige/10 opacity-0 group-hover:opacity-100 transition-opacity z-20 pointer-events-none">
                <div className="space-y-2 text-xs">
                   <div className={cn("flex justify-between items-center font-bold", i18n.language === 'ar' ? 'flex-row-reverse' : 'flex-row')}>
                      <span className="text-brand-beige">{t('assessments.answers_score')}:</span>
                      <span className="text-brand-text">{submission.answers.reduce((acc, a) => acc + a.score, 0)}</span>
                   </div>
                   {submission.adminAdjustment !== 0 && submission.adminAdjustment !== undefined && (
                     <div className={cn(
                       "flex justify-between items-center font-bold",
                       submission.adminAdjustment > 0 ? "text-emerald-600" : "text-brand-red",
                       i18n.language === 'ar' ? 'flex-row-reverse' : 'flex-row'
                     )}>
                        <span className="text-brand-beige">{t('assessments.admin_adj')}:</span>
                        <span>{submission.adminAdjustment > 0 ? `+${submission.adminAdjustment}` : submission.adminAdjustment}</span>
                     </div>
                   )}
                </div>
             </div>
          </div>
        </div>

        {/* Global Feedback Card */}
        {(submission.aiFeedback || submission.adminReviewNotes) && (
          <div className="space-y-6">
            {submission.adminReviewNotes && (
              <motion.div 
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-brand-red rounded-[40px] p-8 text-white relative overflow-hidden shadow-xl shadow-brand-red/10"
              >
                <div className="absolute top-0 left-0 p-4 md:p-6 opacity-10">
                  <Award className="w-16 h-16 md:w-24 md:h-24" />
                </div>
                <div className="relative z-10 space-y-4">
                  <h3 className="text-xl font-black flex items-center gap-3">
                    <CheckCircle2 className="w-5 h-5 text-white" />
                    ملاحظات المعلم
                  </h3>
                  <div className="text-white/90 leading-relaxed font-bold bg-white/10 p-6 rounded-3xl border border-white/20">
                    <p className="whitespace-pre-wrap">{submission.adminReviewNotes}</p>
                  </div>
                </div>
              </motion.div>
            )}

            {submission.aiFeedback && (
              <motion.div 
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-brand-text rounded-[40px] p-8 text-white relative overflow-hidden"
              >
                 <div className="absolute top-0 right-0 p-6 opacity-10">
                   <Brain className="w-16 h-16 md:w-24 md:h-24" />
                 </div>
                 <div className="relative z-10 space-y-4">
                    <h3 className={cn("text-xl font-black flex items-center gap-3", i18n.language === 'en' ? 'flex-row' : 'flex-row-reverse')}>
                      <Brain className="w-5 h-5 text-brand-red" />
                      {t('assessments.ai_analysis')}
                    </h3>
                    <div className="text-white/80 leading-relaxed font-medium bg-white/5 p-6 rounded-3xl border border-white/10 markdown-body">
                       <ReactMarkdown>{submission.aiFeedback}</ReactMarkdown>
                    </div>
                 </div>
              </motion.div>
            )}
          </div>
        )}

        {/* Questions Review */}
        <div className="space-y-6">
            <h3 className={cn("text-2xl font-black text-brand-text flex items-center gap-3", i18n.language === 'en' ? 'flex-row' : 'flex-row-reverse')}>
              <HelpCircle className="w-6 h-6 text-brand-red" />
              {t('assessments.detailed_review')}
            </h3>

           <div className="space-y-4">
              {submission.answers.map((answer, index) => {
                const question = [...assessment.questions.easy, ...assessment.questions.medium, ...assessment.questions.hard].find(q => q.id === answer.questionId);
                if (!question) return null;
                const isExpanded = expandedId === answer.questionId;

                return (
                  <div 
                    key={answer.questionId}
                    className={cn(
                      "bg-white rounded-[32px] border transition-all overflow-hidden",
                      answer.isCorrect ? "border-emerald-100" : "border-rose-100"
                    )}
                  >
                    <button 
                      onClick={() => setExpandedId(isExpanded ? null : answer.questionId)}
                      className={cn("w-full p-8 flex items-start gap-6 hover:bg-brand-cream/10 transition-colors", i18n.language === 'ar' ? 'text-right' : 'text-left')}
                    >
                       <div className={cn(
                         "w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-sm",
                         answer.isCorrect ? "bg-emerald-50 text-emerald-600" : "bg-rose-50 text-brand-red"
                       )}>
                         {answer.isCorrect ? <CheckCircle2 className="w-6 h-6" /> : <XCircle className="w-6 h-6" />}
                       </div>

                       <div className="flex-1 space-y-2 text-right">
                          <div className="flex justify-between items-start">
                            <span className={cn(
                              "px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest",
                              question.difficulty === 'easy' ? "bg-emerald-50 text-emerald-600" :
                              question.difficulty === 'medium' ? "bg-amber-50 text-amber-600" : "bg-rose-50 text-brand-red"
                            )}>
                              {question.difficulty === 'easy' ? 'سهل' : question.difficulty === 'medium' ? 'متوسط' : 'صعب'}
                            </span>
                            <span className="text-brand-beige text-xs font-bold">السؤال {index + 1}</span>
                          </div>
                          <h4 className="text-lg font-black text-brand-text leading-relaxed">
                            {question.text}
                          </h4>
                       </div>

                       <div className="mt-2 text-brand-beige">
                         {isExpanded ? <ChevronUp className="w-6 h-6" /> : <ChevronDown className="w-6 h-6" />}
                       </div>
                    </button>

                    <AnimatePresence>
                      {isExpanded && (
                        <motion.div
                          initial={{ height: 0, opacity: 0 }}
                          animate={{ height: "auto", opacity: 1 }}
                          exit={{ height: 0, opacity: 0 }}
                          className="bg-brand-cream/20 border-t border-brand-beige/10 overflow-hidden"
                        >
                           <div className="p-8 space-y-8">
                             <div className="grid md:grid-cols-2 gap-8">
                                <div className="space-y-2">
                                   <label className="text-[10px] font-black text-brand-beige uppercase tracking-widest">إجابتك</label>
                                   <div className={cn(
                                     "p-4 rounded-2xl font-black",
                                     answer.isCorrect ? "bg-emerald-50 text-emerald-700 border border-emerald-100" : "bg-rose-50 text-brand-red border border-rose-100"
                                   )}>
                                     {answer.userAnswer || "(بدون إجابة)"}
                                   </div>
                                </div>
                                <div className="space-y-2">
                                   <label className="text-[10px] font-black text-brand-beige uppercase tracking-widest">الإجابة الصحيحة</label>
                                   <div className="p-4 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-2xl font-black">
                                     {answer.correctAnswer}
                                   </div>
                                </div>
                             </div>

                             {question.explanation && (
                                <div className="space-y-3 bg-white p-6 rounded-3xl border border-brand-beige/5">
                                   <h5 className="text-sm font-black text-brand-text flex items-center gap-2">
                                     <MessageSquare className="w-4 h-4 text-brand-red" />
                                     شرح الإجابة:
                                   </h5>
                                   <p className="text-brand-beige font-medium leading-relaxed">
                                     {question.explanation}
                                   </p>
                                </div>
                             )}

                             {answer.feedback && (
                                <div className="space-y-3 bg-brand-text/5 p-6 rounded-3xl border border-brand-text/10">
                                   <h5 className="text-sm font-black text-brand-text flex items-center gap-2">
                                     <Brain className="w-4 h-4 text-brand-red" />
                                     تقييم AI:
                                   </h5>
                                   <div className="text-brand-text font-medium leading-relaxed markdown-body">
                                     <ReactMarkdown>{answer.feedback}</ReactMarkdown>
                                   </div>
                                </div>
                             )}
                           </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                );
              })}
           </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "motion/react";
import { useNavigate } from "react-router-dom";
import { 
  ShoppingBag, 
  ShoppingCart,
  Star, 
  Zap, 
  Trophy, 
  Search, 
  Filter,
  CheckCircle2,
  AlertCircle,
  ArrowRight,
  ChevronRight,
  TrendingUp,
  Sparkles,
  LogIn,
} from "lucide-react";
import { 
  collection, 
  query, 
  orderBy, 
  onSnapshot, 
  addDoc, 
  doc, 
  updateDoc, 
  increment,
  serverTimestamp 
} from "firebase/firestore";
import { db, handleFirestoreError, OperationType } from "../../lib/firebase";
import { useAuth } from "../../hooks/useAuth";
import { StoreItem } from "../../types";
import { cn } from "../../lib/utils";
import { SmartImage } from "../../components/ui/SmartImage";
import { useTranslation } from "react-i18next";

export default function Store() {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [items, setItems] = useState<StoreItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [categoryFilter, setCategoryFilter] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [isPurchasing, setIsPurchasing] = useState<string | null>(null);
  const [showConfirm, setShowConfirm] = useState<{ item: StoreItem; quantity: number } | null>(null);
  const [quantities, setQuantities] = useState<Record<string, number>>({});
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  useEffect(() => {
    const q = query(
      collection(db, "storeItems"),
      orderBy("createdAt", "desc")
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => {
        const item = doc.data() as StoreItem;
        const images = item.images || [(item as any).image].filter(Boolean) || [];
        return { id: doc.id, ...item, images } as StoreItem;
      });
      setItems(data);
      setIsLoading(false);
    }, (error) => {
      handleFirestoreError(error, OperationType.LIST, "storeItems");
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handlePurchase = (item: StoreItem) => {
    const quantity = quantities[item.id!] || 1;
    setShowConfirm({ item, quantity });
  };

  const executePurchase = async () => {
    if (!user || !showConfirm) return;
    const { item, quantity } = showConfirm;
    const totalPrice = item.price * quantity;

    setIsPurchasing(item.id!);
    setShowConfirm(null);
    setMessage(null);

    try {
      // 1. Create Purchase record
      await addDoc(collection(db, "purchases"), {
        userId: user.uid,
        userName: user.fullName,
        itemId: item.id,
        itemTitle: item.title,
        pricePaid: totalPrice,
        quantity: quantity,
        status: 'pending',
        purchaseDate: new Date().toISOString()
      });

      // 2. Update user points
      const userRef = doc(db, "users", user.uid);
      await updateDoc(userRef, {
        totalPoints: increment(-totalPrice)
      });

      // 3. Update stock
      const itemRef = doc(db, "storeItems", item.id!);
      await updateDoc(itemRef, {
        stock: increment(-quantity)
      });

      // 4. Notify Admin
      await addDoc(collection(db, "notifications"), {
        title: "طلب جديد من المتجر",
        message: `الطالب ${user.fullName} طلب شراء ${quantity} من "${item.title}" مقابل إجمالي ${totalPrice} نقطة.`,
        type: 'system',
        targetRole: 'admin',
        createdAt: serverTimestamp(),
        readBy: []
      });

      setMessage({ type: 'success', text: t('store.success_purchase', { item: item.title }) });
    } catch (err) {
      console.error("Purchase error:", err);
      setMessage({ type: 'error', text: t('store.error_purchase') });
    } finally {
      setIsPurchasing(null);
      setTimeout(() => setMessage(null), 5000);
    }
  };

  const filteredItems = items.filter(item => {
    const matchesCategory = categoryFilter === "all" || item.category === categoryFilter;
    const matchesSearch = item.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const categories = [
    { id: "all", label: t('store.category_all'), icon: Filter },
    { id: "gift", label: t('store.category_gifts'), icon: Sparkles },
    { id: "workshop", label: t('store.category_workshops'), icon: Zap },
  ];

  return (
    <div className="min-h-screen bg-brand-cream pb-20 px-4 md:px-6 lg:px-12 pt-4 md:pt-8" dir={i18n.language === 'ar' ? 'rtl' : 'ltr'}>
      {/* Header - Refactored for global sidebar */}
      <div className="max-w-7xl mx-auto mb-6 md:mb-12 py-4 md:py-8 lg:py-0">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 md:gap-8">
          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 md:w-14 md:h-14 rounded-xl md:rounded-2xl bg-brand-red flex items-center justify-center text-white shadow-lg shadow-brand-red/20 transform -rotate-6 shrink-0">
                <ShoppingBag className="w-5 h-5 md:w-8 md:h-8" />
              </div>
              <div>
                <h1 className="text-xl md:text-4xl font-black text-brand-text tracking-tight">{t('store.title')}</h1>
                <p className="text-brand-beige font-bold text-xs md:text-sm mt-0.5 md:mt-1">{t('store.subtitle')}</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3 md:gap-6 bg-white p-3 md:p-4 rounded-2xl md:rounded-[32px] border border-brand-beige/10 shadow-sm w-fit">
             <div className="flex flex-col items-end">
                <span className="text-[9px] md:text-[10px] font-black text-brand-beige uppercase tracking-widest leading-none mb-1">{t('store.balance')}</span>
                <span className="text-lg md:text-2xl font-black text-brand-text leading-none">{user?.totalPoints || 0} {t('dashboard.points_label')}</span>
             </div>
             <div className="w-9 h-9 md:w-12 md:h-12 rounded-full bg-amber-50 flex items-center justify-center text-amber-500 shrink-0">
                <Star className="w-4 h-4 md:w-6 md:h-6 fill-current" />
             </div>
          </div>
        </div>
      </div>

      {/* Confirmation Modal */}
      <AnimatePresence>
        {showConfirm && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setShowConfirm(null)}
              className="absolute inset-0 bg-brand-text/40 backdrop-blur-sm"
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.9, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.9, y: 20 }}
              className="relative w-full max-w-md bg-white rounded-[48px] p-10 shadow-2xl text-center border border-brand-cream"
            >
              <div className="w-14 h-14 md:w-20 md:h-20 bg-brand-red/10 rounded-full flex items-center justify-center mx-auto mb-4 md:mb-6">
                <ShoppingCart className="w-7 h-7 md:w-10 md:h-10 text-brand-red" />
              </div>
              <h3 className="text-2xl font-black text-brand-text mb-2">{t('store.confirm_title')}</h3>
              <div className="flex items-center justify-center gap-2 mb-4 bg-brand-red/5 py-2 px-4 rounded-full w-fit mx-auto">
                <span className="text-brand-red font-black text-lg">{showConfirm.quantity}</span>
                <span className="text-brand-beige text-xs font-bold">{t('store.units')}</span>
              </div>
              <p className="text-brand-beige font-bold leading-relaxed mb-8">
                {t('store.confirm_msg', { item: showConfirm.item.title, price: showConfirm.item.price * showConfirm.quantity })}
              </p>

              <div className="grid grid-cols-2 gap-4">
                <button
                  onClick={() => setShowConfirm(null)}
                  className="py-4 rounded-[24px] font-black text-brand-beige border-2 border-brand-cream hover:bg-brand-cream transition-all"
                >
                  {t('dashboard.cancel')}
                </button>
                <button
                  onClick={executePurchase}
                  className="py-4 rounded-[24px] font-black text-white bg-brand-red hover:bg-brand-text shadow-lg shadow-brand-red/20 transition-all"
                >
                  {t('store.confirm_title')}
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <div className="max-w-7xl mx-auto space-y-6 md:space-y-12">
        {/* Search and Filter */}
        <div className="flex flex-col lg:flex-row items-center gap-4 md:gap-6">
          <div className="relative w-full lg:w-96">
            <Search className={cn("absolute top-1/2 -translate-y-1/2 w-4 md:w-5 h-4 md:h-5 text-brand-beige", i18n.language === 'ar' ? 'right-4 md:right-5' : 'left-4 md:left-5')} />
            <input 
              type="text"
              placeholder={t('store.search_placeholder')}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className={cn(
                "w-full bg-white border border-brand-beige/10 rounded-2xl md:rounded-[24px] py-3 md:py-4 outline-none focus:border-brand-red/20 transition-all font-bold text-brand-text text-sm md:text-base",
                i18n.language === 'ar' ? 'pr-11 md:pr-14 pl-5 md:pl-6' : 'pl-11 md:pl-14 pr-5 md:pr-6'
              )}
            />
          </div>

          <div className="flex items-center gap-2 md:gap-3 overflow-x-auto pb-2 w-full lg:w-auto hide-scrollbar">
            {categories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setCategoryFilter(cat.id)}
                className={cn(
                  "px-4 py-2.5 md:px-6 md:py-4 rounded-xl md:rounded-[20px] font-black text-xs md:text-sm whitespace-nowrap transition-all flex items-center gap-2 md:gap-3 border",
                  categoryFilter === cat.id 
                    ? "bg-brand-red text-white border-brand-red shadow-lg shadow-brand-red/20" 
                    : "bg-white text-brand-beige border-brand-beige/10 hover:border-brand-red/20"
                )}
              >
                <cat.icon className="w-3.5 h-3.5 md:w-4 md:h-4" />
                {cat.label}
              </button>
            ))}
          </div>
        </div>

        {/* Message HUD */}
        <AnimatePresence>
          {message && (
            <motion.div
              initial={{ opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className={cn(
                "p-6 rounded-[32px] flex items-center gap-4 shadow-xl border",
                message.type === 'success' 
                  ? "bg-emerald-50 text-emerald-700 border-emerald-100" 
                  : "bg-rose-50 text-rose-700 border-rose-100"
              )}
            >
              {message.type === 'success' ? <CheckCircle2 className="w-6 h-6" /> : <AlertCircle className="w-6 h-6" />}
              <p className="font-black text-lg">{message.text}</p>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Items Grid */}
        {isLoading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
            {[1, 2, 3, 4].map(i => (
              <div key={i} className="h-96 bg-white animate-pulse rounded-[40px] border border-brand-beige/5" />
            ))}
          </div>
        ) : filteredItems.length === 0 ? (
          <div className="py-32 text-center space-y-4">
            <div className="w-14 h-14 md:w-20 md:h-20 bg-brand-cream rounded-full flex items-center justify-center mx-auto text-brand-beige">
              <ShoppingBag className="w-7 h-7 md:w-10 md:h-10" />
            </div>
            <h3 className="text-2xl font-black text-brand-text">{t('assessments.no_results')}</h3>
            <p className="text-brand-beige font-bold">{t('assessments.no_results_subtitle')}</p>
          </div>
        ) : (
          <div className={cn("grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8", i18n.language === 'ar' ? 'text-right' : 'text-left')}>
            {filteredItems.map((item, idx) => (
              <StoreItemCard 
                key={item.id} 
                item={item} 
                idx={idx} 
                onPurchase={handlePurchase}
                isPurchasing={isPurchasing === item.id}
                userPoints={user?.totalPoints || 0}
                quantity={quantities[item.id!] || 1}
                setQuantity={(q) => setQuantities(prev => ({ ...prev, [item.id!]: q }))}
              />
            ))}
          </div>
        )}


        {/* Info Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-8 mt-6 md:mt-12">
            <div className="bg-brand-red/5 p-5 md:p-8 rounded-3xl md:rounded-[40px] border border-brand-red/10 flex items-center gap-4 md:gap-6">
                <div className="w-12 h-12 md:w-16 md:h-16 rounded-xl md:rounded-2xl bg-brand-red text-white flex items-center justify-center shrink-0">
                    <Zap className="w-6 h-6 md:w-8 md:h-8" />
                </div>
                <div>
                    <h4 className="font-black text-base md:text-xl text-brand-text mb-0.5 md:mb-1">{t('store.info_points_title')}</h4>
                    <p className="text-brand-beige text-[11px] md:text-xs font-bold leading-relaxed">{t('store.info_points_desc')}</p>
                </div>
            </div>
